# Load the grids from the session directory
import os, json
import re

RLM_SESSION_DIR = os.environ['RLM_SESSION_DIR']
session_folder = RLM_SESSION_DIR

# Load all demo pairs and test input
pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):')

with open(f'{session_folder}/../sessions/{os.path.basename(session_folder)}.jsonl') as f:
    content = f.read()

input_output = {}

pos = 0
for match in pattern.finditer(content):
    title = match.group(1)
    size = int(match.group(2))
    rows_data = content[match.end():match.end()+size*size+1].strip().split('\n')
    grid = [[int(x) for x in row.split()] for row in rows_data[:size]]

    # Parse which grid this is
    if 'Demo pair 1 input' in title:
        input_output['demo1_in'] = grid
    elif 'Demo pair 1 output' in title:
        input_output['demo1_out'] = grid
    elif 'Test input' in title:
        input_output['test'] = grid

# Display the grids to understand the pattern
print("Demo 1 input shape:", len(input_output['demo1_in']), input_output['demo1_in'][0])
print("Demo 1 output shape:", len(input_output['demo1_out']), input_output['demo1_out'][0])
print("Test input shape:", len(input_output['test']), input_output['test'][0])
print()

# Check colors in demo input
def color_counts(grid):
    from collections import Counter
    return Counter([c for row in grid for c in row])
print("Demo 1 input colors:", color_counts(input_output['demo1_in']))
print("Test input colors:", color_counts(input_output['test']))
print()

# Output always has 3s preserved - test hypothesis: checkerboard fill based on parity
def test_checkerboard(harness_grid):
    """Test if output is checkerboard: cell[3 if both row+col odd else 0 for both r,c in harness_grid]"""
    h, w = len(harness_grid), len(harness_grid[0])
    output_grid = [[0]*w for _ in range(h)]

    # Find the cross (row and column with all 3s)
    row_of_3s = None
    col_of_3s = None

    for r in range(h):
        if all(harness_grid[r][c] == 3 for c in range(w)):
            row_of_3s = r
            break

    if row_of_3s is None:
        return harness_grid  # No horizontal bar

    for c in range(w):
        if all(harness_grid[r][c] == 3 for r in range(h)):
            col_of_3s = c
            break

    # Fill checkerboard pattern
    for r in range(h):
        for c in range(w):
            if harness_grid[r][c] == 3:
                output_grid[r][c] = 3
            else:
                if (r + c) % 2 == 1:
                    output_grid[r][c] = 4
                else:
                    output_grid[r][c] = 0

    return output_grid

# Test on demo 1
demo_out_pred = test_checkerboard(input_output['demo1_in'])
match = all(demo_out_pred[r][c] == input_output['demo1_out'][r][c] for r in range(len(demo_out_pred)) for c in range(len(demo_out_pred[0])))
print("Checkerboard prediction matches demo output:", match)

# Show where they differ if any
if not match:
    print("Differences found!")
    for r in range(len(input_output['demo1_out'])):
        for c in range(len(input_output['demo1_out'][0])):
            if demo_out_pred[r][c] != input_output['demo1_out'][r][c]:
                print(f"  ({r},{c}): predicted={demo_out_pred[r][c]}, actual={input_output['demo1_out'][r][c]}")

